import{_ as t,o as e,c as i,a4 as l}from"./chunks/framework.vNSRaLQv.js";const u=JSON.parse('{"title":"MyBilibili 重构执行计划","description":"","frontmatter":{"title":"MyBilibili 重构执行计划","date":"2026-08-05T00:00:00.000Z"},"headers":[],"relativePath":"posts/04-refactoring-execution-plan.md","filePath":"posts/04-refactoring-execution-plan.md"}'),s={name:"posts/04-refactoring-execution-plan.md"};function r(d,a,n,o,h,p){return e(),i("div",null,[...a[0]||(a[0]=[l(`<h1 id="mybilibili-重构执行计划" tabindex="-1">MyBilibili 重构执行计划 <a class="header-anchor" href="#mybilibili-重构执行计划" aria-label="Permalink to &quot;MyBilibili 重构执行计划&quot;">​</a></h1><h2 id="_1-总览" tabindex="-1">1. 总览 <a class="header-anchor" href="#_1-总览" aria-label="Permalink to &quot;1. 总览&quot;">​</a></h2><h3 id="_1-1-目标" tabindex="-1">1.1 目标 <a class="header-anchor" href="#_1-1-目标" aria-label="Permalink to &quot;1.1 目标&quot;">​</a></h3><p>从 Spring Cloud Alibaba 微服务重构为云原生标准架构：</p><table tabindex="0"><thead><tr><th>项</th><th>现状</th><th>目标</th></tr></thead><tbody><tr><td>服务发现</td><td>Nacos</td><td>etcd</td></tr><tr><td>消息队列</td><td>RocketMQ</td><td>NATS（CNCF 孵化）</td></tr><tr><td>缓存</td><td>Redis</td><td>Redis（保留）</td></tr><tr><td>服务调用</td><td>Feign</td><td>gRPC（CNCF 毕业）</td></tr><tr><td>网关</td><td>Spring Cloud Gateway</td><td>Traefik（K8s Gateway API 实现）</td></tr><tr><td>存储</td><td>MySQL + MongoDB</td><td>MySQL + SQLite</td></tr><tr><td>语言</td><td>Java 全栈</td><td>Go + Java (GraalVM)</td></tr><tr><td>可观测性</td><td>无</td><td>Prometheus + Loki + OpenTelemetry</td></tr></tbody></table><h3 id="_1-2-现状盘点" tabindex="-1">1.2 现状盘点 <a class="header-anchor" href="#_1-2-现状盘点" aria-label="Permalink to &quot;1.2 现状盘点&quot;">​</a></h3><ul><li>现有 Java 服务：8 个（account-social, ai, common, content-interaction, gateway, mq, search-recommend, video-media + admin）</li><li>代码规模：约 509 个 Java 文件</li><li>紧耦合点：RocketMQTemplate、@FeignClient、Nacos 配置注入</li><li>已抽象：StorageService（MinioStorageService 实现）</li></ul><h3 id="_1-3-资源清单" tabindex="-1">1.3 资源清单 <a class="header-anchor" href="#_1-3-资源清单" aria-label="Permalink to &quot;1.3 资源清单&quot;">​</a></h3><p><strong>硬件（12 设备）：</strong></p><ul><li>4 台 Android 盒子（1GB RAM，eMMC）</li><li>6 台手机（Android，可 Linux 化）</li><li>2 台电脑（1 台主力机做 media 转码）</li></ul><p><strong>基础设施：</strong></p><ul><li>MySQL：部署在老电脑（主数据库，支付强一致）</li><li>SQLite：盒子本地缓存/离线降级</li><li>NATS：消息队列（老电脑，~20MB）</li><li>etcd：服务发现（老电脑）</li><li>Redis：缓存（老电脑）</li><li>MinIO：对象存储（主力机）</li><li>Traefik：网关（盒子入口）</li></ul><hr><h2 id="_2-阶段划分" tabindex="-1">2. 阶段划分 <a class="header-anchor" href="#_2-阶段划分" aria-label="Permalink to &quot;2. 阶段划分&quot;">​</a></h2><h3 id="phase-0-准备-1-周" tabindex="-1">Phase 0：准备（1 周） <a class="header-anchor" href="#phase-0-准备-1-周" aria-label="Permalink to &quot;Phase 0：准备（1 周）&quot;">​</a></h3><p><strong>目标：</strong> 建立基础，统一开发环境</p><ul><li>[ ] 定义并提交基础设施抽象层接口（03 文档）</li><li>[ ] 建立 Go 微服务脚手架（core/realtime/search/ads）</li><li>[ ] 配置管理（etcd）接入测试</li><li>[ ] 确定 protobuf 定义目录结构</li><li>[ ] 明确 MySQL/SQLite 数据边界</li></ul><p><strong>产出：</strong></p><ul><li><code>proto/</code> 目录（gRPC 接口定义）</li><li><code>go.mod</code> 各服务</li><li>抽象层接口代码（go 包）</li></ul><h3 id="phase-1-部署-traefik-网关-1-周" tabindex="-1">Phase 1：部署 Traefik 网关（1 周） <a class="header-anchor" href="#phase-1-部署-traefik-网关-1-周" aria-label="Permalink to &quot;Phase 1：部署 Traefik 网关（1 周）&quot;">​</a></h3><p><strong>目标：</strong> 用 Traefik 替换 Java Spring Cloud Gateway</p><ul><li>[ ] 部署 Traefik 到盒子（docker 或二进制）</li><li>[ ] 配置 etcd 服务发现（Traefik → etcd 对接）</li><li>[ ] 配置 HTTP → gRPC 路由</li><li>[ ] 配置 JWT 认证中间件</li><li>[ ] 配置限流中间件</li><li>[ ] 配置 Let&#39;s Encrypt 自动证书</li></ul><p><strong>验证：</strong> Java 服务通过 Traefik 代理访问，JWT 认证生效</p><h3 id="phase-2-核心服务迁移-4-周" tabindex="-1">Phase 2：核心服务迁移（4 周） <a class="header-anchor" href="#phase-2-核心服务迁移-4-周" aria-label="Permalink to &quot;Phase 2：核心服务迁移（4 周）&quot;">​</a></h3><p><strong>目标：</strong> core 服务用 Go 重写（用户/关注/内容/评论/点赞/收藏/分享）</p><ul><li>[ ] 用户模块（注册/登录/资料）</li><li>[ ] 内容模块（视频/稿件 CRUD）</li><li>[ ] 互动模块（评论/点赞/收藏/分享）</li><li>[ ] MySQL 访问（现有表结构复用）</li><li>[ ] 缓存层（Redis CacheStore）</li></ul><p><strong>验证：</strong> core 与 Java 版功能对齐（对拍测试）</p><h3 id="phase-3-实时服务-2-周" tabindex="-1">Phase 3：实时服务（2 周） <a class="header-anchor" href="#phase-3-实时服务-2-周" aria-label="Permalink to &quot;Phase 3：实时服务（2 周）&quot;">​</a></h3><p><strong>目标：</strong> realtime 服务（弹幕/消息/通知 WebSocket）</p><ul><li>[ ] WebSocket 网关（连接管理）</li><li>[ ] 弹幕广播（NATS 分发）</li><li>[ ] 消息通知（SSE/WS 推送）</li><li>[ ] 会话状态（Redis，无状态化）</li></ul><p><strong>验证：</strong> 双端（web + 移动）收发弹幕</p><h3 id="phase-4-搜索服务-2-周" tabindex="-1">Phase 4：搜索服务（2 周） <a class="header-anchor" href="#phase-4-搜索服务-2-周" aria-label="Permalink to &quot;Phase 4：搜索服务（2 周）&quot;">​</a></h3><p><strong>目标：</strong> search 服务（搜索/推荐/热榜）</p><ul><li>[ ] Bleve 索引（替代 ES）</li><li>[ ] 索引同步（监听 NATS 业务事件）</li><li>[ ] 推荐排序（简单规则）</li><li>[ ] 热榜计算（定时聚合）</li></ul><p><strong>验证：</strong> 搜索结果与 ES 版一致</p><h3 id="phase-5-媒体服务-4-周" tabindex="-1">Phase 5：媒体服务（4 周） <a class="header-anchor" href="#phase-5-媒体服务-4-周" aria-label="Permalink to &quot;Phase 5：媒体服务（4 周）&quot;">​</a></h3><p><strong>目标：</strong> media 服务（Java GraalVM）</p><ul><li>[ ] 视频转码（FFmpeg 子进程）</li><li>[ ] 直播接入（SRS + HLS/FLV）</li><li>[ ] AI 字幕（Whisper 子进程）</li><li>[ ] AI 总结（DeepSeek API）</li><li>[ ] GraalVM Native Image 编译</li></ul><p><strong>验证：</strong> 转码任务从 NATS JetStream 消费并处理</p><h3 id="phase-6-广告-商城服务-3-周" tabindex="-1">Phase 6：广告/商城服务（3 周） <a class="header-anchor" href="#phase-6-广告-商城服务-3-周" aria-label="Permalink to &quot;Phase 6：广告/商城服务（3 周）&quot;">​</a></h3><p><strong>目标：</strong> ads（Go）+ store（Java GraalVM）</p><ul><li>[ ] ads：广告投放/展示计费/点击计费</li><li>[ ] store：商城/订单/支付/退款/对账</li><li>[ ] 支付事务保障（MySQL 强一致）</li></ul><h3 id="phase-7-部署与-ci-cd-2-周" tabindex="-1">Phase 7：部署与 CI/CD（2 周） <a class="header-anchor" href="#phase-7-部署与-ci-cd-2-周" aria-label="Permalink to &quot;Phase 7：部署与 CI/CD（2 周）&quot;">​</a></h3><p><strong>目标：</strong> 12 设备集群 + 自动部署 + 可观测性</p><ul><li>[ ] GitHub Actions 多架构编译（arm64/amd64）</li><li>[ ] SSH/rsync 部署脚本</li><li>[ ] 设备 agent（服务注册/健康检查/日志）</li><li>[ ] systemd 服务单元</li><li>[ ] Prometheus + Grafana 监控</li><li>[ ] Loki 日志聚合</li><li>[ ] OpenTelemetry 链路追踪</li></ul><hr><h2 id="_3-每个阶段的完成标准" tabindex="-1">3. 每个阶段的完成标准 <a class="header-anchor" href="#_3-每个阶段的完成标准" aria-label="Permalink to &quot;3. 每个阶段的完成标准&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>完成标准</th></tr></thead><tbody><tr><td>Phase 0</td><td>抽象层接口 + 脚手架可编译，配置可切换</td></tr><tr><td>Phase 1</td><td>Traefik 代理全部 Java 服务，JWT/限流生效</td></tr><tr><td>Phase 2</td><td>core 功能与 Java 版对拍一致</td></tr><tr><td>Phase 3</td><td>弹幕实时收发，无状态（重启不断连可恢复）</td></tr><tr><td>Phase 4</td><td>搜索/热榜与 ES 版结果一致</td></tr><tr><td>Phase 5</td><td>转码/字幕/总结全流程跑通</td></tr><tr><td>Phase 6</td><td>下单-支付-退款链路完整</td></tr><tr><td>Phase 7</td><td>一键部署到 12 设备，监控可见</td></tr></tbody></table><hr><h2 id="_4-风险与对策" tabindex="-1">4. 风险与对策 <a class="header-anchor" href="#_4-风险与对策" aria-label="Permalink to &quot;4. 风险与对策&quot;">​</a></h2><table tabindex="0"><thead><tr><th>风险</th><th>概率</th><th>影响</th><th>对策</th></tr></thead><tbody><tr><td>GraalVM 编译失败</td><td>中</td><td>高</td><td>保守用 JVM，二进制化非强制</td></tr><tr><td>FFmpeg 子进程兼容</td><td>中</td><td>中</td><td>打包 ffmpeg 静态二进制，用子进程不 JNI</td></tr><tr><td>数据迁移错误</td><td>中</td><td>高</td><td>先用配置指向旧库，逐步切换</td></tr><tr><td>功能对拍不一致</td><td>高</td><td>中</td><td>每个服务对拍测试后才替换</td></tr><tr><td>盒子资源不足</td><td>低</td><td>高</td><td>服务按需分配，盒子只跑业务</td></tr></tbody></table><hr><h2 id="_5-里程碑" tabindex="-1">5. 里程碑 <a class="header-anchor" href="#_5-里程碑" aria-label="Permalink to &quot;5. 里程碑&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>M1（第 1 周）  抽象层 + 脚手架就绪</span></span>
<span class="line"><span>M2（第 2 周）  Traefik 网关跑通全链路</span></span>
<span class="line"><span>M3（第 6 周）  core 迁移完成（对拍通过）</span></span>
<span class="line"><span>M4（第 8 周）  realtime 实时链路通</span></span>
<span class="line"><span>M5（第 10 周） search 通</span></span>
<span class="line"><span>M6（第 14 周） media 通（GraalVM）</span></span>
<span class="line"><span>M7（第 17 周） ads + store 通</span></span>
<span class="line"><span>M8（第 19 周） 12 设备集群部署完成 + 可观测性就绪</span></span></code></pre></div><hr><h2 id="_6-分支管理" tabindex="-1">6. 分支管理 <a class="header-anchor" href="#_6-分支管理" aria-label="Permalink to &quot;6. 分支管理&quot;">​</a></h2><p>基于当前仓库结构：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>master      → 云微服务主线（Java，正在运行）</span></span>
<span class="line"><span>monolith    → 纯单体版（历史）</span></span>
<span class="line"><span>springboot3 → Spring Boot 3 升级线（历史）</span></span>
<span class="line"><span>web/java/admin/obs-plugin → 各源仓库历史</span></span></code></pre></div><p><strong>重构开发流程：</strong></p><ul><li>新增 <code>refactor/</code> 前缀分支（如 <code>refactor/core-go</code>）</li><li>每个服务一个分支，完成对拍后合并 master</li><li>抽象层接口先入库 master，稳定后各服务切换</li></ul><p><strong>合并规则：</strong></p><ul><li>功能分支保持 master 最新</li><li>每个合并保持可运行</li><li>不强制重写历史（保留合并提交）</li></ul>`,62)])])}const b=t(s,[["render",r]]);export{u as __pageData,b as default};
